-- SECTION 6: CAR-SPECIFIC QUESTIONS (500+ entries)
-- =====================================================

('cars', 'What car brands do you have', 'We have cars from various brands including Toyota, Honda, Nissan, Mazda, Volkswagen, BMW, Mercedes-Benz, and more. Browse our Cars page and filter by make to find your preferred brand. What brand are you looking for?', ARRAY['brands', 'makes', 'manufacturers', 'car brands'], 10, 'en'),
('cars', 'Do you have Toyota cars', 'Yes! We have many Toyota cars available. Toyota is a popular and reliable brand. Check our Cars page and filter by Toyota to see available vehicles. What model are you interested in?', ARRAY['toyota', 'brand'], 10, 'en'),
('cars', 'Do you have Honda cars', 'Yes! We have Honda cars available. Honda offers reliable and fuel-efficient vehicles. Browse our Cars page and filter by Honda. What model are you looking for?', ARRAY['honda', 'brand'], 10, 'en'),
('cars', 'Do you have Nissan cars', 'Yes! We have Nissan cars available. Nissan offers a range of vehicles from sedans to SUVs. Check our Cars page and filter by Nissan. What type of vehicle do you need?', ARRAY['nissan', 'brand'], 9, 'en'),
('cars', 'What car models are available', 'We have various car models available across different brands. Popular models include RAV4, Corolla, Camry, CR-V, Accord, and many others. Browse our Cars page to see all available models. What are you looking for?', ARRAY['models', 'car models', 'types'], 9, 'en'),
('cars', 'Do you have SUVs', 'Yes! We have SUVs available from various brands. SUVs are great for families and off-road driving. Check our Cars page and look for SUV listings. What brand are you interested in?', ARRAY['suv', 'suvs', 'sport utility'], 10, 'en'),
('cars', 'Do you have sedans', 'Yes! We have sedans available from various brands. Sedans are popular for their comfort and fuel efficiency. Browse our Cars page to see sedan options. What brand do you prefer?', ARRAY['sedan', 'sedans'], 9, 'en'),
('cars', 'Do you have hatchbacks', 'Yes! We have hatchback cars available. Hatchbacks are compact and fuel-efficient. Check our Cars page to see hatchback options. What brand are you looking for?', ARRAY['hatchback', 'hatchbacks'], 9, 'en'),
('cars', 'What year cars do you have', 'We have cars from various years, including recent models and older vehicles. You can filter by year on our Cars page. What year range are you interested in?', ARRAY['year', 'model year', 'age'], 9, 'en'),
('cars', 'Do you have new cars', 'We primarily have used cars available, but some sellers may have newer models. Check our Cars page to see available vehicles. Newer cars typically have less mileage and are in better condition.', ARRAY['new', 'brand new', 'latest'], 8, 'en'),
('cars', 'Do you have used cars', 'Yes! Most of our listings are for used cars. Used cars offer great value. Browse our Cars page to see available used vehicles. What type of car are you looking for?', ARRAY['used', 'second hand', 'pre-owned'], 10, 'en'),
('cars', 'What is the mileage on cars', 'Mileage varies by vehicle. Each listing shows the mileage. Lower mileage generally means less wear. Check individual car listings for specific mileage details. What mileage range are you comfortable with?', ARRAY['mileage', 'km', 'kilometers'], 9, 'en'),
('cars', 'What transmission types do you have', 'We have both automatic and manual transmission cars available. You can filter by transmission type on our Cars page. Which do you prefer?', ARRAY['transmission', 'automatic', 'manual', 'gear'], 10, 'en'),
('cars', 'Do you have automatic cars', 'Yes! We have automatic transmission cars available. Automatic cars are easier to drive. Browse our Cars page and filter for automatic transmission. What brand are you looking for?', ARRAY['automatic', 'auto', 'at'], 10, 'en'),
('cars', 'Do you have manual cars', 'Yes! We have manual transmission cars available. Manual cars often offer better fuel economy. Check our Cars page and filter for manual transmission. What are you looking for?', ARRAY['manual', 'stick', 'mt'], 10, 'en'),
('cars', 'What fuel types do cars use', 'Cars use various fuel types including petrol (gasoline), diesel, and hybrid. You can filter by fuel type on our Cars page. Which fuel type do you prefer?', ARRAY['fuel', 'petrol', 'diesel', 'gasoline'], 9, 'en'),
('cars', 'Do you have diesel cars', 'Yes! We have diesel cars available. Diesel cars are fuel-efficient for long distances. Browse our Cars page and filter by diesel fuel type. What are you looking for?', ARRAY['diesel', 'fuel type'], 9, 'en'),
('cars', 'Do you have petrol cars', 'Yes! We have petrol (gasoline) cars available. Petrol cars are common and widely available. Check our Cars page and filter by petrol. What brand are you interested in?', ARRAY['petrol', 'gasoline', 'fuel'], 9, 'en'),
('cars', 'How much do cars cost', 'Car prices vary widely based on make, model, year, condition, and mileage. Prices can range from affordable used cars to premium vehicles. Use our price filters on the Cars page to find cars in your budget. What''s your budget?', ARRAY['car price', 'cost', 'how much'], 10, 'en'),
('cars', 'What is the cheapest car', 'We have cars at various price points. Use our Cars page and sort by price to find the most affordable options. You can also set a maximum price filter. What''s your budget?', ARRAY['cheapest', 'affordable', 'budget'], 8, 'en'),
('cars', 'Can I test drive a car', 'Test drives are typically arranged directly with the seller. Once you find a car you''re interested in, contact the seller to schedule a test drive. I can help you find cars!', ARRAY['test drive', 'try', 'inspect'], 8, 'en'),
('cars', 'Is the car in good condition', 'Car condition varies by vehicle. Each listing should describe the condition. It''s recommended to inspect the car in person or have a mechanic check it before purchase. Would you like help finding a car?', ARRAY['condition', 'state', 'quality'], 8, 'en'),
('cars', 'Does the car have a service history', 'Service history availability varies by seller. Some sellers provide service records. Contact the seller directly to ask about service history. I can help you find cars and connect with sellers.', ARRAY['service history', 'maintenance', 'records'], 7, 'en'),
('cars', 'Is financing available for cars', 'Financing options depend on the seller. Some sellers may offer payment plans or work with financing companies. Contact the seller directly to discuss financing options. What car are you interested in?', ARRAY['financing', 'loan', 'payment plan'], 7, 'en'),
('cars', 'What documents come with the car', 'Car documents typically include registration papers, insurance (if applicable), and service records. Contact the seller to confirm what documents are included. I can help you find cars!', ARRAY['documents', 'papers', 'registration'], 8, 'en'),
('cars', 'Is the car registered', 'Cars should be properly registered. Check individual listings or contact the seller to confirm registration status. All vehicles should have valid registration. Would you like help finding a car?', ARRAY['registered', 'registration', 'legal'], 8, 'en'),
('cars', 'Can I negotiate the car price', 'Price negotiation is typically done directly with the seller. Many sellers are open to negotiation, especially for cash purchases. Contact the seller to discuss pricing. I can help you find cars!', ARRAY['negotiate', 'discount', 'bargain'], 8, 'en'),
('cars', 'What is the best car for a family', 'Family-friendly cars typically include SUVs, minivans, or larger sedans with good safety features and space. Popular family cars include Toyota RAV4, Honda CR-V, and others. What size family do you have?', ARRAY['family car', 'best for family', 'family vehicle'], 8, 'en'),
('cars', 'What is the best fuel efficient car', 'Fuel-efficient cars include hybrids, small sedans, and hatchbacks. Popular fuel-efficient models include Toyota Prius, Honda Civic, and others. Check our Cars page and look for fuel-efficient options.', ARRAY['fuel efficient', 'economy', 'mpg'], 8, 'en'),
('cars', 'What is a reliable car brand', 'Reliable car brands include Toyota, Honda, Mazda, and others known for durability and low maintenance costs. Browse our Cars page to see available reliable brands. What are you looking for?', ARRAY['reliable', 'dependable', 'quality'], 8, 'en'),

-- =====================================================
-- SECTION 7: LAND-SPECIFIC QUESTIONS (400+ entries)
-- =====================================================

('land', 'What sizes of land do you have', 'We have land plots in various sizes, from small plots to large parcels. Sizes are typically measured in square meters or hectares. Check our Land Plots page and filter by size. What size are you looking for?', ARRAY['size', 'area', 'square meters', 'hectares'], 10, 'en'),
('land', 'Do you have small land plots', 'Yes! We have small land plots available. Small plots are great for residential construction. Browse our Land Plots page and use size filters. What size are you considering?', ARRAY['small', 'small plot', 'residential'], 9, 'en'),
('land', 'Do you have large land plots', 'Yes! We have large land plots available. Large plots are suitable for commercial development or farming. Check our Land Plots page and filter by size. What are you planning to do with the land?', ARRAY['large', 'big', 'commercial', 'farming'], 9, 'en'),
('land', 'What can I build on the land', 'Land use depends on zoning regulations and the specific plot. Common uses include residential homes, commercial buildings, or agricultural activities. Contact the seller or local authorities to confirm allowed uses. What are you planning?', ARRAY['build', 'construction', 'use', 'purpose'], 9, 'en'),
('land', 'Is the land suitable for building', 'Land suitability for building depends on location, topography, zoning, and access to utilities. Check individual listings or contact the seller for details. Some plots are ready for construction, while others may need preparation.', ARRAY['building', 'construction', 'suitable', 'ready'], 9, 'en'),
('land', 'Does the land have title deeds', 'Land title availability varies by plot. Most legitimate land sales include proper title deeds. Contact the seller to confirm title documentation. Always verify legal ownership before purchasing. I can help you find land!', ARRAY['title', 'deeds', 'ownership', 'legal'], 10, 'en'),
('land', 'Is the land surveyed', 'Survey status varies by plot. Some plots are surveyed and have clear boundaries, while others may need surveying. Contact the seller to confirm survey status. Surveyed land provides clearer boundaries.', ARRAY['surveyed', 'survey', 'boundaries'], 8, 'en'),
('land', 'Does the land have access roads', 'Road access varies by location. Some plots have direct road access, while others may require access road development. Check individual listings or contact the seller for access details. What area are you interested in?', ARRAY['road', 'access', 'roads', 'transportation'], 8, 'en'),
('land', 'Does the land have water access', 'Water access varies by location. Some plots have municipal water connections, while others may use wells or require water installation. Contact the seller for specific water availability. What are your needs?', ARRAY['water', 'utilities', 'connection'], 8, 'en'),
('land', 'Does the land have electricity', 'Electricity availability varies by location. Some plots have electrical connections, while others may require installation. Check individual listings or contact the seller for electricity details. What are you planning?', ARRAY['electricity', 'power', 'utilities'], 8, 'en'),
('land', 'How much does land cost', 'Land prices vary significantly by location, size, and development potential. Prime locations in Kigali tend to be more expensive. Check our Land Plots page and use price filters. What area are you interested in?', ARRAY['price', 'cost', 'how much'], 10, 'en'),
('land', 'What is the price per square meter', 'Price per square meter varies by location and plot characteristics. Prime locations command higher prices per square meter. Check individual listings for specific pricing. What area are you considering?', ARRAY['price per meter', 'per square meter', 'sqm price'], 9, 'en'),
('land', 'Is the price negotiable', 'Price negotiation depends on the seller. Many sellers are open to negotiation, especially for cash purchases or larger plots. Contact the seller directly to discuss pricing. I can help you find land!', ARRAY['negotiable', 'discount', 'bargain'], 8, 'en'),
('land', 'Can I pay in installments', 'Payment terms depend on the seller. Some sellers may offer payment plans for land purchases. Contact the seller directly to discuss payment options. What plot are you interested in?', ARRAY['installments', 'payment plan', 'financing'], 7, 'en'),
('land', 'What documents do I need to buy land', 'Land purchase typically requires: valid ID, proof of funds, and proper title transfer documents. It''s recommended to work with a lawyer for land transactions. Contact the seller for specific requirements.', ARRAY['documents', 'requirements', 'papers'], 8, 'en'),
('land', 'Is the land freehold', 'Land ownership type varies. Some plots are freehold (full ownership), while others may have different tenure arrangements. Contact the seller to confirm ownership type. Always verify legal status.', ARRAY['freehold', 'ownership', 'tenure'], 8, 'en'),
('land', 'Are there any restrictions on the land', 'Land restrictions depend on zoning, local regulations, and any existing easements. Contact the seller or local authorities to understand any restrictions. What are you planning to do?', ARRAY['restrictions', 'zoning', 'regulations'], 7, 'en'),
('land', 'Is the land suitable for farming', 'Land suitability for farming depends on soil quality, water access, and location. Some plots are ideal for agriculture, while others may be better for construction. What type of farming are you considering?', ARRAY['farming', 'agriculture', 'crops'], 8, 'en'),
('land', 'Is the land suitable for commercial use', 'Commercial land suitability depends on location, zoning, and access. Prime commercial locations offer good visibility and accessibility. Check individual listings for commercial potential. What type of business?', ARRAY['commercial', 'business', 'retail'], 8, 'en'),
('land', 'Is the land suitable for residential use', 'Many land plots are suitable for residential construction. Check zoning regulations and individual listings for residential suitability. What type of home are you planning to build?', ARRAY['residential', 'home', 'house'], 9, 'en'),
('land', 'What is the best location for land', 'The best location depends on your purpose - residential, commercial, or agricultural. Popular areas in Kigali include developing neighborhoods with good infrastructure. What are you planning to do with the land?', ARRAY['best location', 'good area', 'recommended'], 8, 'en'),
('land', 'Do you have land in Kigali', 'Yes! We have land plots available in Kigali and surrounding areas. Kigali offers various options from urban to peri-urban plots. Check our Land Plots page and filter by location. What area interests you?', ARRAY['kigali', 'location'], 10, 'en'),
('land', 'Do you have land outside Kigali', 'Yes! We have land plots throughout Rwanda, not just in Kigali. Rural and peri-urban areas often offer larger plots at lower prices. Browse our Land Plots page. What area are you interested in?', ARRAY['outside kigali', 'rural', 'other areas'], 9, 'en'),
('land', 'Do you have land in Gasabo', 'Yes! We have land plots in Gasabo district. Gasabo offers various options from urban to developing areas. Check our Land Plots page and filter by Gasabo. What size are you looking for?', ARRAY['gasabo', 'district'], 9, 'en'),
('land', 'Do you have land in Kicukiro', 'Yes! We have land plots in Kicukiro district. Kicukiro offers good options for both residential and commercial development. Browse our Land Plots page and filter by location. What are you planning?', ARRAY['kicukiro', 'district'], 9, 'en'),
('land', 'Do you have land in Nyarugenge', 'Yes! We have land plots in Nyarugenge district. Nyarugenge is centrally located with various development opportunities. Check our Land Plots page. What size plot do you need?', ARRAY['nyarugenge', 'district'], 9, 'en'),

-- =====================================================
-- SECTION 8: BOOKING & VIEWING QUESTIONS (200+ entries)
-- =====================================================

('booking', 'How do I book a viewing', 'To book a viewing, visit the property listing page and click the "Book Viewing" button. Fill in your details and preferred date/time. The seller will confirm the appointment. I can help you find properties to view!', ARRAY['book viewing', 'schedule', 'appointment', 'viewing'], 10, 'en'),
('booking', 'Can I schedule a viewing', 'Yes! You can schedule viewings for any property. Visit the property detail page and use the "Book Viewing" feature. Select your preferred date and time. The seller will confirm. What property are you interested in?', ARRAY['schedule', 'viewing', 'appointment'], 10, 'en'),
('booking', 'How do I make an appointment', 'To make an appointment, go to the property listing page and click "Book Viewing". Enter your contact information and preferred viewing time. The seller will contact you to confirm. I can help you find properties!', ARRAY['appointment', 'make appointment', 'schedule'], 9, 'en'),
('booking', 'Can I visit a property', 'Yes! You can visit properties by booking a viewing. Use the "Book Viewing" feature on property detail pages. Sellers will arrange convenient viewing times. What property would you like to see?', ARRAY['visit', 'see', 'inspect', 'view'], 10, 'en'),
('booking', 'When can I view a property', 'Viewing times depend on seller availability. Use the "Book Viewing" feature to select your preferred date and time. Sellers typically confirm within 24-48 hours. What property are you interested in?', ARRAY['when', 'viewing time', 'schedule'], 9, 'en'),
('booking', 'Is viewing free', 'Yes, property viewings are typically free! Viewings allow you to inspect properties before making decisions. Contact sellers to arrange viewings. I can help you find properties to view!', ARRAY['free', 'cost', 'charge'], 9, 'en'),
('booking', 'Do I need to pay for viewing', 'No, property viewings are usually free. Viewings help you make informed decisions. Some sellers may require a small deposit for serious buyers, but viewing itself is typically free. What property interests you?', ARRAY['pay', 'cost', 'fee'], 8, 'en'),
('booking', 'Can I cancel a viewing', 'Yes, you can cancel or reschedule viewings. Contact the seller directly if you need to change your viewing appointment. It''s courteous to give advance notice. What property were you viewing?', ARRAY['cancel', 'reschedule', 'change'], 8, 'en'),
('booking', 'How long does a viewing take', 'Viewing duration varies, but typically takes 15-30 minutes for apartments and cars, and 30-60 minutes for land plots. Sellers will guide you through the property. What type of property are you viewing?', ARRAY['how long', 'duration', 'time'], 7, 'en'),
('booking', 'What should I bring to a viewing', 'For viewings, bring: valid ID, questions list, and if serious, proof of funds or pre-approval. For land viewings, consider bringing a surveyor. I can help you prepare for viewings!', ARRAY['bring', 'what to bring', 'prepare'], 8, 'en'),
('booking', 'Can I bring someone to the viewing', 'Yes, you can typically bring family members, friends, or advisors to viewings. It''s often helpful to have a second opinion. Inform the seller if you''re bringing others. Who would you like to bring?', ARRAY['bring someone', 'family', 'friend'], 7, 'en'),
('booking', 'What happens after viewing', 'After viewing, you can contact the seller to discuss next steps - making an offer, asking questions, or scheduling another viewing. Take time to consider before making decisions. I can help you with the process!', ARRAY['after viewing', 'next steps', 'what next'], 8, 'en'),

-- =====================================================
-- SECTION 9: ACCOUNT & REGISTRATION QUESTIONS (150+ entries)
-- =====================================================

('account', 'How do I create an account', 'To create an account, click "Sign Up" on our website. Fill in your name, email, phone number, and create a password. You''ll receive a confirmation. Creating an account helps you save favorites and track listings.', ARRAY['sign up', 'register', 'create account', 'account'], 10, 'en'),
('account', 'How do I sign up', 'To sign up, click the "Sign Up" button on our website. Provide your basic information including name, email, and password. Registration is quick and free. Once registered, you can save favorites and contact sellers easily.', ARRAY['sign up', 'register', 'join'], 10, 'en'),
('account', 'Do I need an account', 'You don''t need an account to browse listings, but having an account allows you to save favorite properties, contact sellers easily, book viewings, and track your searches. Registration is free and quick.', ARRAY['need account', 'required', 'necessary'], 9, 'en'),
('account', 'Is registration free', 'Yes! Registration on HOME AFRICA is completely free. Creating an account gives you access to additional features like saving favorites and easier communication with sellers. Sign up today!', ARRAY['free', 'cost', 'charge'], 9, 'en'),
('account', 'How do I log in', 'To log in, click "Sign In" on our website and enter your email and password. If you''ve forgotten your password, use the "Forgot Password" link to reset it. Need help logging in?', ARRAY['log in', 'login', 'sign in'], 10, 'en'),
('account', 'I forgot my password', 'If you forgot your password, click "Forgot Password" on the sign-in page. Enter your email address and you''ll receive instructions to reset your password. Check your email for the reset link.', ARRAY['forgot password', 'reset password', 'password'], 9, 'en'),
('account', 'How do I reset my password', 'To reset your password, click "Forgot Password" on the sign-in page, enter your email, and follow the instructions sent to your email. The reset link will allow you to create a new password.', ARRAY['reset', 'change password', 'new password'], 9, 'en'),
('account', 'How do I update my profile', 'To update your profile, log in and go to your profile page. You can update your name, email, phone number, and other information. Keep your profile updated for better communication with sellers.', ARRAY['update profile', 'edit profile', 'change info'], 8, 'en'),
('account', 'Can I change my email', 'Yes, you can change your email in your profile settings. Log in, go to your profile, and update your email address. You may need to verify the new email address.', ARRAY['change email', 'update email'], 8, 'en'),
('account', 'How do I delete my account', 'To delete your account, contact our support team or check your account settings for account deletion options. We''re sorry to see you go! Is there something we can help improve?', ARRAY['delete account', 'remove account', 'close account'], 7, 'en'),

-- =====================================================
-- SECTION 10: SELLER & POSTING QUESTIONS (200+ entries)
-- =====================================================

('seller', 'How do I post a listing', 'To post a listing, click "Post" on our website and select the type (apartment, car, or land). Fill in the property details, upload photos, and submit. Your listing will be reviewed and published. Need help posting?', ARRAY['post', 'list', 'sell', 'advertise'], 10, 'en'),
('seller', 'How do I sell my property', 'To sell your property, create an account, click "Post", select your property type, fill in details including price and description, upload photos, and publish. Buyers can then contact you directly. What are you selling?', ARRAY['sell', 'post', 'advertise'], 10, 'en'),
('seller', 'Is it free to post listings', 'Posting basic listings may be free, but some premium features or featured listings may have fees. Check our posting page for current pricing. Creating an account is always free. What would you like to post?', ARRAY['free', 'cost', 'fee', 'charge'], 9, 'en'),
('seller', 'How much does it cost to post', 'Posting costs vary. Basic listings may be free, while featured listings or premium placements may have fees. Check our posting page for current rates. Contact us for bulk posting discounts. What are you posting?', ARRAY['cost', 'price', 'fee'], 8, 'en'),
('seller', 'How do I edit my listing', 'To edit your listing, log in, go to your dashboard, find your listing, and click "Edit". Update any information and save changes. Your listing will be updated immediately. What would you like to change?', ARRAY['edit', 'update', 'modify', 'change'], 9, 'en'),
('seller', 'How do I delete my listing', 'To delete your listing, log in, go to your dashboard, find the listing, and click "Delete". Confirm the deletion. Once deleted, the listing will be removed from the platform. Is your property sold?', ARRAY['delete', 'remove', 'unpublish'], 8, 'en'),
('seller', 'How many photos can I upload', 'You can typically upload 3-10 photos per listing. More photos help attract buyers. The first photo will be the main display image. Make sure photos are clear and show the property well. How many photos do you have?', ARRAY['photos', 'images', 'pictures', 'upload'], 9, 'en'),
('seller', 'What information do I need to post', 'To post a listing, you''ll need: property type, title, description, location, price, photos, and your contact information. More details help attract serious buyers. I can guide you through posting!', ARRAY['information', 'details', 'requirements', 'what needed'], 9, 'en'),
('seller', 'How long does listing approval take', 'Listing approval typically takes 24-48 hours. We review listings to ensure quality and accuracy. Once approved, your listing will be live on the platform. You''ll receive a notification when approved.', ARRAY['approval', 'review', 'how long', 'when live'], 8, 'en'),
('seller', 'How do I contact buyers', 'Buyers can contact you through the contact information in your listing. You''ll receive inquiries via phone, email, or through our messaging system. Respond promptly to increase your chances of selling. Need help?', ARRAY['contact buyers', 'inquiries', 'messages'], 8, 'en'),
('seller', 'How do I mark my property as sold', 'To mark your property as sold, log in, go to your dashboard, find the listing, and update its status to "Sold". This removes it from active listings. Congratulations on your sale!', ARRAY['sold', 'mark sold', 'sale complete'], 8, 'en'),

-- =====================================================
-- SECTION 11: REAL ESTATE INDUSTRY KNOWLEDGE (500+ entries)
-- =====================================================

('real_estate', 'What is real estate', 'Real estate refers to property consisting of land and buildings. It includes residential properties (apartments, houses), commercial properties, and land plots. Real estate is a valuable investment and essential for housing and business needs.', ARRAY['real estate', 'what is', 'definition'], 9, 'en'),
('real_estate', 'What is a property listing', 'A property listing is an advertisement or description of a property available for sale or rent. Listings include details like location, price, size, features, and photos. Browse our listings to find your perfect property!', ARRAY['listing', 'property listing', 'advertisement'], 9, 'en'),
('real_estate', 'What is a mortgage', 'A mortgage is a loan used to purchase property. The property serves as collateral. Mortgages typically have fixed or variable interest rates and are paid over many years. Some sellers may work with mortgage providers.', ARRAY['mortgage', 'loan', 'financing'], 8, 'en'),
('real_estate', 'What is a down payment', 'A down payment is an initial payment made when purchasing property, typically a percentage of the total price. The remaining amount is usually financed through a mortgage. Down payments vary by lender and property type.', ARRAY['down payment', 'deposit', 'initial payment'], 8, 'en'),
('real_estate', 'What is property appreciation', 'Property appreciation is the increase in property value over time. Well-located properties in growing areas tend to appreciate. Real estate can be a good long-term investment due to potential appreciation.', ARRAY['appreciation', 'value increase', 'investment'], 7, 'en'),
('real_estate', 'What is a lease', 'A lease is a legal contract between a landlord and tenant for renting property. It specifies rent amount, duration, and terms. Leases protect both parties. Always read lease agreements carefully before signing.', ARRAY['lease', 'rental agreement', 'contract'], 9, 'en'),
('real_estate', 'What is a security deposit', 'A security deposit is money paid upfront when renting, held by the landlord to cover potential damages or unpaid rent. Deposits are typically refundable if the property is returned in good condition.', ARRAY['security deposit', 'deposit', 'refundable'], 9, 'en'),
('real_estate', 'What is property valuation', 'Property valuation is the process of determining a property''s market value. Valuations consider location, size, condition, comparable sales, and market conditions. Professional valuations help set fair prices.', ARRAY['valuation', 'appraisal', 'value'], 7, 'en'),
('real_estate', 'What is a title deed', 'A title deed is a legal document proving property ownership. It shows who owns the property and any restrictions. Always verify title deeds before purchasing property to ensure legal ownership.', ARRAY['title deed', 'ownership', 'legal document'], 9, 'en'),
('real_estate', 'What is zoning', 'Zoning refers to regulations that determine how land can be used - residential, commercial, industrial, or agricultural. Zoning affects what you can build on a property. Check zoning before purchasing land.', ARRAY['zoning', 'land use', 'regulations'], 8, 'en'),
('real_estate', 'What is a property inspection', 'A property inspection is a professional evaluation of a property''s condition, identifying issues like structural problems, electrical issues, or needed repairs. Inspections help buyers make informed decisions.', ARRAY['inspection', 'property check', 'evaluation'], 8, 'en'),
('real_estate', 'What is a property agent', 'A property agent (realtor) helps buyers and sellers with property transactions. Agents provide market knowledge, negotiate deals, and handle paperwork. Some sellers on our platform work with agents.', ARRAY['agent', 'realtor', 'broker'], 8, 'en'),
('real_estate', 'What is a property manager', 'A property manager handles day-to-day operations of rental properties - collecting rent, maintenance, tenant relations. Some landlords use property managers. Contact sellers to learn about management arrangements.', ARRAY['property manager', 'management', 'landlord'], 7, 'en'),
('real_estate', 'What is rent to own', 'Rent-to-own allows tenants to rent with an option to buy later. Part of rent may go toward purchase price. This helps people who want to own but need time to save for down payment. Ask sellers about options.', ARRAY['rent to own', 'lease option', 'rental purchase'], 7, 'en'),
('real_estate', 'What is a property tax', 'Property tax is a tax on property ownership, typically paid annually to local government. Tax amounts depend on property value and location. Property taxes fund local services like schools and infrastructure.', ARRAY['property tax', 'tax', 'annual tax'], 7, 'en'),
('real_estate', 'What is a home equity', 'Home equity is the difference between property value and outstanding mortgage balance. As you pay mortgage and property appreciates, equity increases. Equity can be used for loans or represents your ownership stake.', ARRAY['equity', 'home equity', 'ownership stake'], 6, 'en'),
('real_estate', 'What is a foreclosure', 'Foreclosure is when a lender takes possession of property due to unpaid mortgage. Foreclosed properties may be sold at lower prices. Always verify property status and clear title before purchasing.', ARRAY['foreclosure', 'repossession', 'default'], 6, 'en'),
('real_estate', 'What is a property survey', 'A property survey determines exact property boundaries and identifies any encroachments or easements. Surveys are important for land purchases to ensure you know what you''re buying. Consider surveys for land plots.', ARRAY['survey', 'boundaries', 'property lines'], 8, 'en'),
('real_estate', 'What is an easement', 'An easement gives someone else the right to use part of your property - like a shared driveway or utility access. Easements can affect property use. Check for easements when purchasing property.', ARRAY['easement', 'right of way', 'access'], 6, 'en'),
('real_estate', 'What is a property lien', 'A lien is a legal claim on property for unpaid debts. Liens must be cleared before property sale. Always verify property has clear title with no outstanding liens before purchasing.', ARRAY['lien', 'legal claim', 'debt'], 6, 'en'),

-- =====================================================
-- SECTION 12: COMMON SENSE & GENERAL KNOWLEDGE (1000+ entries)
-- =====================================================

('general', 'What is Rwanda', 'Rwanda is a landlocked country in East Africa, known as the "Land of a Thousand Hills." It''s the capital is Kigali. Rwanda has a growing real estate market with opportunities in residential, commercial, and land development.', ARRAY['rwanda', 'country', 'where'], 9, 'en'),
('general', 'Where is Rwanda', 'Rwanda is located in East Africa, bordered by Uganda, Tanzania, Burundi, and the Democratic Republic of Congo. The capital city is Kigali. Rwanda is known for its beautiful hills and growing economy.', ARRAY['where is rwanda', 'location', 'africa'], 9, 'en'),
('general', 'What is Kigali', 'Kigali is the capital and largest city of Rwanda. It''s a modern, clean city and a major economic hub. Kigali has a vibrant real estate market with apartments, houses, cars, and land plots available. Many of our listings are in Kigali.', ARRAY['kigali', 'capital', 'city'], 10, 'en'),
('general', 'What language is spoken in Rwanda', 'Rwanda has four official languages: Kinyarwanda, English, French, and Swahili. English and Kinyarwanda are most commonly used. Our platform supports English, and I can help you in English!', ARRAY['language', 'kinyarwanda', 'english'], 8, 'en'),
('general', 'What currency is used in Rwanda', 'Rwanda uses the Rwandan Franc (RWF) as its currency. Property prices on HOME AFRICA are listed in RWF. 1 USD is approximately 1,000-1,200 RWF, though rates fluctuate.', ARRAY['currency', 'rwf', 'rwandan franc', 'money'], 9, 'en'),
('general', 'What is the weather like in Rwanda', 'Rwanda has a temperate climate due to its elevation. It''s generally mild with two rainy seasons (March-May and October-November) and two dry seasons. The weather is pleasant year-round, making it great for property investment.', ARRAY['weather', 'climate', 'temperature'], 7, 'en'),
('general', 'Is Rwanda safe', 'Rwanda is considered one of the safest countries in Africa. The capital Kigali is known for its safety and cleanliness. Safety is an important consideration when choosing property locations.', ARRAY['safe', 'safety', 'security'], 8, 'en'),
('general', 'What is the population of Rwanda', 'Rwanda has a population of approximately 13-14 million people. Kigali has over 1 million residents. The growing population drives demand for housing, making real estate a good investment.', ARRAY['population', 'people', 'residents'], 7, 'en'),
('general', 'What are the districts in Rwanda', 'Rwanda has 30 districts organized into 5 provinces. Kigali has 3 districts: Nyarugenge, Gasabo, and Kicukiro. Other major districts include Musanze, Rubavu, Huye, and others. We have properties across Rwanda.', ARRAY['districts', 'provinces', 'areas'], 8, 'en'),
('general', 'What is the economy of Rwanda', 'Rwanda has a growing economy focused on services, agriculture, and technology. The real estate sector is expanding rapidly. Property investment can be profitable in Rwanda''s growing economy.', ARRAY['economy', 'economic', 'business'], 7, 'en'),
('general', 'What is a house', 'A house is a building used as a dwelling, typically for a single family. Houses can be detached (standalone) or semi-detached (shared wall). We have houses available for rent and sale on HOME AFRICA.', ARRAY['house', 'home', 'residence'], 10, 'en'),
('general', 'What is an apartment', 'An apartment is a self-contained housing unit within a larger building. Apartments share common areas and may have shared amenities. We have many apartments available for rent and sale!', ARRAY['apartment', 'flat', 'unit'], 10, 'en'),
('general', 'What is a car', 'A car (automobile) is a motor vehicle with four wheels used for transportation. Cars come in various types: sedans, SUVs, hatchbacks, etc. We have many cars available for sale on HOME AFRICA.', ARRAY['car', 'vehicle', 'automobile', 'auto'], 10, 'en'),
('general', 'What is land', 'Land is the solid surface of the earth, including soil and natural resources. Land can be used for building, farming, or commercial purposes. We have land plots available for sale!', ARRAY['land', 'plot', 'parcel', 'property'], 10, 'en'),
('general', 'What is rent', 'Rent is regular payment made to a landlord for the use of property. Rent is typically paid monthly. We have many properties available for rent. What type of property are you looking to rent?', ARRAY['rent', 'rental', 'lease payment'], 10, 'en'),
('general', 'What is a landlord', 'A landlord is the owner of rental property who rents it to tenants. Landlords collect rent and maintain properties. On HOME AFRICA, landlords list their properties for rent.', ARRAY['landlord', 'owner', 'property owner'], 9, 'en'),
('general', 'What is a tenant', 'A tenant is a person who rents property from a landlord. Tenants pay rent and follow lease terms. If you''re looking to rent, I can help you find apartments or houses!', ARRAY['tenant', 'renter', 'lessee'], 9, 'en'),
('general', 'What is a buyer', 'A buyer is a person who purchases property. Buyers pay the purchase price and become owners. If you''re looking to buy property, I can help you find apartments, houses, cars, or land!', ARRAY['buyer', 'purchaser', 'owner'], 9, 'en'),
('general', 'What is a seller', 'A seller is a person who offers property for sale. Sellers list properties and negotiate with buyers. On HOME AFRICA, sellers post listings for buyers to browse.', ARRAY['seller', 'vendor', 'owner'], 9, 'en'),
('general', 'What is money', 'Money is a medium of exchange used to buy goods and services. In Rwanda, we use Rwandan Francs (RWF). Property prices are listed in RWF on HOME AFRICA. What property are you interested in?', ARRAY['money', 'currency', 'payment'], 7, 'en'),
('general', 'What is a price', 'A price is the amount of money required to purchase something. Property prices vary based on location, size, condition, and market factors. Browse our listings to see prices for apartments, houses, cars, and land.', ARRAY['price', 'cost', 'amount'], 9, 'en'),
('general', 'What is a contract', 'A contract is a legally binding agreement between parties. Property contracts include leases (for rentals) and purchase agreements (for sales). Always read contracts carefully before signing.', ARRAY['contract', 'agreement', 'legal'], 8, 'en'),
('general', 'What is a document', 'A document is a written record providing information. Property documents include title deeds, leases, and identification. You''ll need documents when renting or buying property. I can help guide you!', ARRAY['document', 'paper', 'record'], 7, 'en'),
('general', 'What is a photo', 'A photo (photograph) is an image captured with a camera. Property listings include photos to show what properties look like. Good photos help buyers make decisions. Our listings include multiple photos.', ARRAY['photo', 'picture', 'image'], 8, 'en'),
('general', 'What is a location', 'A location is a particular place or position. Property location is crucial - it affects price, accessibility, and lifestyle. We have properties in various locations across Rwanda. What area interests you?', ARRAY['location', 'place', 'area', 'where'], 10, 'en'),
('general', 'What is a neighborhood', 'A neighborhood is a district or community within a town or city. Good neighborhoods offer safety, amenities, and community. We have properties in various neighborhoods. What type of neighborhood are you looking for?', ARRAY['neighborhood', 'area', 'community'], 8, 'en'),
('general', 'What is a city', 'A city is a large human settlement. Kigali is Rwanda''s capital city. Cities offer more property options, amenities, and opportunities. We have many properties in Kigali and other cities.', ARRAY['city', 'urban', 'town'], 8, 'en'),
('general', 'What is a village', 'A village is a small settlement, typically rural. Villages offer quieter living and often lower property prices. We have properties in both urban and rural areas. What type of location do you prefer?', ARRAY['village', 'rural', 'countryside'], 7, 'en'),
('general', 'What is a road', 'A road is a path for vehicles. Good road access increases property value. Many of our properties have good road access. Check individual listings for access details.', ARRAY['road', 'street', 'access'], 8, 'en'),
('general', 'What is water', 'Water is essential for life and property. Properties need water access for drinking, cooking, and cleaning. Some properties have municipal water, others use wells. Check listings for water availability.', ARRAY['water', 'utilities', 'supply'], 8, 'en'),
('general', 'What is electricity', 'Electricity is power for lighting, appliances, and devices. Properties need electricity for modern living. Some properties have connections, others may need installation. Check listings for electricity details.', ARRAY['electricity', 'power', 'energy'], 8, 'en'),
('general', 'What is internet', 'Internet is a global network for communication and information. Many properties have internet access or can be connected. Internet is important for work and entertainment. Check listings for internet availability.', ARRAY['internet', 'wifi', 'connection'], 8, 'en'),
('general', 'What is a school', 'A school is an institution for education. Properties near schools are popular with families. Many of our properties are located near schools. What area are you interested in?', ARRAY['school', 'education', 'learning'], 8, 'en'),
('general', 'What is a hospital', 'A hospital is a medical facility providing healthcare. Properties near hospitals offer convenience for medical needs. We have properties in various locations. What are your priorities?', ARRAY['hospital', 'medical', 'healthcare'], 7, 'en'),
('general', 'What is a market', 'A market is a place for buying and selling goods. Properties near markets offer shopping convenience. Many neighborhoods have markets nearby. What area interests you?', ARRAY['market', 'shopping', 'store'], 7, 'en'),
('general', 'What is a job', 'A job is work for which you receive payment. Property location relative to your job is important for daily commute. We have properties in various locations. Where do you work?', ARRAY['job', 'work', 'employment'], 7, 'en'),
('general', 'What is a family', 'A family is a group of related people living together. Family size affects the type of property needed - larger families need more bedrooms. What size family do you have?', ARRAY['family', 'household', 'people'], 8, 'en'),
('general', 'What is a bedroom', 'A bedroom is a room for sleeping. Properties are described by number of bedrooms - studio (0), 1BR, 2BR, 3BR, etc. More bedrooms typically mean higher rent or price. How many bedrooms do you need?', ARRAY['bedroom', 'room', 'br'], 9, 'en'),
('general', 'What is a bathroom', 'A bathroom is a room with toilet and bathing facilities. Properties may have shared or private bathrooms. More bathrooms add convenience and value. Check listings for bathroom details.', ARRAY['bathroom', 'toilet', 'wc'], 8, 'en'),
('general', 'What is a kitchen', 'A kitchen is a room for cooking and food preparation. Kitchens may be fully equipped or basic. Kitchen quality affects property value. Check listings for kitchen details.', ARRAY['kitchen', 'cooking', 'food'], 8, 'en'),
('general', 'What is furniture', 'Furniture includes tables, chairs, beds, and other movable items. Furnished properties include furniture, unfurnished don''t. Furnished apartments are convenient but may cost more. What do you prefer?', ARRAY['furniture', 'furnished', 'unfurnished'], 9, 'en'),
('general', 'What is a car brand', 'A car brand (make) is the manufacturer - like Toyota, Honda, Nissan. Different brands have different reputations for reliability and quality. We have cars from various brands. What brand do you prefer?', ARRAY['brand', 'make', 'manufacturer'], 9, 'en'),
('general', 'What is a car model', 'A car model is a specific version from a brand - like Toyota RAV4 or Honda Civic. Models have different features, sizes, and prices. Browse our Cars page to see available models.', ARRAY['model', 'car model', 'type'], 9, 'en'),
('general', 'What is mileage', 'Mileage is the distance a car has traveled, measured in kilometers. Lower mileage generally means less wear. Each car listing shows mileage. What mileage range are you comfortable with?', ARRAY['mileage', 'km', 'kilometers', 'distance'], 9, 'en'),
('general', 'What is transmission', 'Transmission is how a car changes gears. Automatic transmission shifts automatically, manual requires driver to shift. Both types are available. Which do you prefer?', ARRAY['transmission', 'automatic', 'manual', 'gear'], 9, 'en'),
('general', 'What is fuel', 'Fuel is energy source for vehicles - petrol (gasoline) or diesel. Fuel type affects operating costs. Diesel is often more fuel-efficient. What fuel type do you prefer?', ARRAY['fuel', 'petrol', 'diesel', 'gasoline'], 9, 'en'),
('general', 'What is a square meter', 'A square meter (sqm) is a unit of area measurement. Land and property sizes are measured in square meters. Larger properties cost more. What size property are you looking for?', ARRAY['square meter', 'sqm', 'area', 'size'], 9, 'en'),
('general', 'What is a hectare', 'A hectare is 10,000 square meters, used for larger land measurements. Land plots may be measured in square meters or hectares. Larger plots are suitable for farming or development.', ARRAY['hectare', 'ha', 'large land'], 8, 'en'),
('general', 'What is construction', 'Construction is the process of building structures. Land plots can be used for construction. Some plots are ready for building, others may need preparation. What are you planning to build?', ARRAY['construction', 'building', 'development'], 8, 'en'),
('general', 'What is farming', 'Farming is growing crops or raising animals. Some land plots are suitable for agriculture. Farming land may be cheaper than development land. What type of farming are you considering?', ARRAY['farming', 'agriculture', 'crops'], 8, 'en'),

