-- SECTION 13: DRIVING SCHOOL QUESTIONS (200+ entries)
-- =====================================================

('driving_school', 'Do you have driving schools', 'Yes! HOME AFRICA connects you with driving schools. Visit our Driving School page to learn about provisional licenses, permanent licenses, and combined license options. I can help you find driving school information!', ARRAY['driving school', 'driving', 'license', 'learn to drive'], 10, 'en'),
('driving_school', 'How do I get a driving license', 'To get a driving license in Rwanda, you need to complete driving school training and pass tests. HOME AFRICA can connect you with driving schools offering provisional, permanent, or combined licenses. What type do you need?', ARRAY['driving license', 'license', 'how to get'], 10, 'en'),
('driving_school', 'What is a provisional license', 'A provisional license is a temporary license allowing you to learn and practice driving with restrictions. It''s a step toward getting a permanent license. Visit our Driving School page for provisional license options.', ARRAY['provisional', 'temporary license', 'learner'], 9, 'en'),
('driving_school', 'What is a permanent license', 'A permanent license is a full driving license with no restrictions. You get it after completing training and passing tests. Visit our Driving School page for permanent license programs.', ARRAY['permanent license', 'full license', 'driving license'], 9, 'en'),
('driving_school', 'What is a combined license', 'A combined license program covers both provisional and permanent license training in one package. It''s convenient if you want to complete everything together. Check our Driving School page for combined options.', ARRAY['combined license', 'package', 'both'], 9, 'en'),
('driving_school', 'How much does driving school cost', 'Driving school costs vary by program type and school. Provisional, permanent, and combined licenses have different prices. Visit our Driving School page to see options and pricing. What program interests you?', ARRAY['cost', 'price', 'how much', 'fee'], 9, 'en'),
('driving_school', 'How long does driving school take', 'Driving school duration varies by program. Provisional licenses may take a few weeks, permanent licenses longer. Combined programs cover both. Contact driving schools for specific timelines. What program are you considering?', ARRAY['how long', 'duration', 'time', 'weeks'], 8, 'en'),
('driving_school', 'What do I need for driving school', 'Requirements typically include: valid ID, medical certificate, photos, and payment. Specific requirements vary by school and license type. Contact driving schools directly for exact requirements. I can help you find schools!', ARRAY['requirements', 'what needed', 'documents'], 8, 'en'),
('driving_school', 'Do I need a car for driving school', 'Driving schools typically provide training vehicles. You don''t need your own car for lessons. Schools have vehicles for practice. Once licensed, you can buy a car - we have many available!', ARRAY['car needed', 'vehicle', 'training car'], 8, 'en'),
('driving_school', 'Can I learn to drive', 'Yes! Anyone can learn to drive by attending driving school and getting proper training. HOME AFRICA connects you with driving schools. Visit our Driving School page to get started. What type of license do you need?', ARRAY['learn', 'learn to drive', 'training'], 9, 'en'),

