('location', 'Properties in Nyarugenge', 'Yes! We have properties in Nyarugenge district. Nyarugenge is one of Kigali''s three districts, centrally located. Browse our listings and filter by Nyarugenge. What type of property are you looking for?', ARRAY['nyarugenge', 'district', 'kigali'], 9, 'en'),
('location', 'Properties in Gasabo', 'Yes! We have properties in Gasabo district. Gasabo is one of Kigali''s districts with many residential and commercial options. Check our listings and filter by Gasabo. What are you looking for?', ARRAY['gasabo', 'district', 'kigali'], 9, 'en'),
('location', 'Properties in Kicukiro', 'Yes! We have properties in Kicukiro district. Kicukiro is one of Kigali''s districts offering various property options. Browse our listings and filter by Kicukiro. What type of property interests you?', ARRAY['kicukiro', 'district', 'kigali'], 9, 'en'),
('location', 'Properties in Nyarutarama', 'Yes! We have properties in Nyarutarama, a popular area in Gasabo district. Nyarutarama is known for upscale residential properties. Check our Apartments page and filter by location. What are you looking for?', ARRAY['nyarutarama', 'area', 'gasabo'], 9, 'en'),
('location', 'Properties in Kimisagara', 'Yes! We have properties in Kimisagara, a well-located area in Nyarugenge district. Kimisagara offers good residential options. Browse our listings and filter by location. What type of property do you need?', ARRAY['kimisagara', 'area', 'nyarugenge'], 9, 'en'),
('location', 'Properties in Remera', 'Yes! We have properties in Remera, a popular area in Gasabo district. Remera offers various residential and commercial options. Check our listings and filter by Remera. What are you interested in?', ARRAY['remera', 'area', 'gasabo'], 9, 'en'),
('location', 'Properties in Kimironko', 'Yes! We have properties in Kimironko, an area in Gasabo district. Kimironko offers good property options. Browse our listings and filter by location. What type of property are you looking for?', ARRAY['kimironko', 'area', 'gasabo'], 9, 'en'),
('location', 'Properties in Gisozi', 'Yes! We have properties in Gisozi, an area in Gasabo district. Gisozi offers various residential options. Check our listings and filter by location. What are you looking for?', ARRAY['gisozi', 'area', 'gasabo'], 8, 'en'),
('location', 'Properties in Kacyiru', 'Yes! We have properties in Kacyiru, an area in Gasabo district. Kacyiru is well-located with good amenities. Browse our listings and filter by location. What type of property interests you?', ARRAY['kacyiru', 'area', 'gasabo'], 8, 'en'),
('location', 'Properties in Musanze', 'Yes! We have properties in Musanze district. Musanze is in Northern Province, known for tourism and agriculture. We have properties throughout Rwanda. What type of property are you looking for?', ARRAY['musanze', 'district', 'northern'], 8, 'en'),
('location', 'Properties in Rubavu', 'Yes! We have properties in Rubavu district. Rubavu is in Western Province, near Lake Kivu. We have properties across Rwanda. Browse our listings and filter by location. What are you interested in?', ARRAY['rubavu', 'district', 'western'], 8, 'en'),
('location', 'Properties in Huye', 'Yes! We have properties in Huye district. Huye is in Southern Province, home to the National University. We have properties throughout Rwanda. What type of property do you need?', ARRAY['huye', 'district', 'southern'], 8, 'en'),

