('listings', 'Got any houses', 'Yes! We have many houses available. Browse our Apartments page where houses and apartments are listed. You can filter by location, price, and size. What area are you interested in?', ARRAY['got', 'have', 'any', 'houses'], 9, 'en'),
('listings', 'Any apartments available', 'Yes! We have many apartments available. Check our Apartments page to see all listings. You can filter by location, price, and bedrooms. What are you looking for?', ARRAY['any', 'available', 'apartments'], 9, 'en'),
('listings', 'Got cars', 'Yes! We have many cars available. Visit our Cars page to browse vehicles. You can filter by make, model, year, and price. What type of car are you looking for?', ARRAY['got', 'have', 'cars'], 9, 'en'),
('listings', 'Any land for sale', 'Yes! We have land plots for sale. Check our Land Plots page to see available properties. You can filter by location, size, and price. What area interests you?', ARRAY['any', 'land', 'for sale'], 9, 'en'),
('listings', 'Show me what you have', 'We have apartments, houses, cars, and land plots available! Browse our website by category - Apartments, Cars, or Land. Each category has filters to help you find exactly what you need. What are you looking for?', ARRAY['show', 'what', 'have', 'available'], 9, 'en'),
('listings', 'What''s available', 'We have many properties available including apartments, houses, cars, and land plots. Browse our website to see all listings. You can filter by category, location, and price. What type of property interests you?', ARRAY['whats available', 'available', 'what have'], 9, 'en'),
('listings', 'What do you offer', 'We offer a platform to find apartments, houses, cars, and land plots. Browse our listings by category. Each category has detailed filters. What are you looking for?', ARRAY['offer', 'what', 'have'], 9, 'en'),
('listings', 'Tell me about your properties', 'We have apartments, houses, cars, and land plots available throughout Rwanda. Each property listing includes details like location, price, size, and photos. Browse our website to see all options. What interests you?', ARRAY['tell me', 'about', 'properties'], 8, 'en'),
('listings', 'I''m searching for apartments', 'Great! I can help you search for apartments. Visit our Apartments page to browse all available listings. You can filter by location, price, bedrooms, and amenities. What are your preferences?', ARRAY['searching', 'looking', 'find', 'apartments'], 10, 'en'),
('listings', 'I''m searching for houses', 'Great! I can help you search for houses. Check our Apartments page where houses and apartments are listed. Use filters to narrow your search. What area are you interested in?', ARRAY['searching', 'looking', 'find', 'houses'], 10, 'en'),
('listings', 'I''m searching for cars', 'Great! I can help you search for cars. Visit our Cars page to browse vehicles. Use filters for make, model, year, and price. What type of car are you looking for?', ARRAY['searching', 'looking', 'find', 'cars'], 10, 'en'),
('listings', 'I''m searching for land', 'Great! I can help you search for land plots. Check our Land Plots page to see available properties. Use filters for location, size, and price. What are you looking for?', ARRAY['searching', 'looking', 'find', 'land'], 10, 'en'),
('listings', 'Help me find an apartment', 'I''d be happy to help you find an apartment! Visit our Apartments page or tell me your preferences - location, price range, number of bedrooms. I can guide you to the right listings. What are you looking for?', ARRAY['help', 'find', 'apartment'], 10, 'en'),
('listings', 'Help me find a house', 'I''d be happy to help you find a house! Check our Apartments page where houses are listed. Tell me your preferences and I can help narrow your search. What area are you interested in?', ARRAY['help', 'find', 'house'], 10, 'en'),
('listings', 'Help me find a car', 'I''d be happy to help you find a car! Visit our Cars page to browse vehicles. Tell me what you''re looking for - make, model, price range - and I can help guide you. What type of car do you need?', ARRAY['help', 'find', 'car'], 10, 'en'),
('listings', 'Help me find land', 'I''d be happy to help you find land! Check our Land Plots page. Tell me your preferences - location, size, price range - and I can help you search. What are you planning to do with the land?', ARRAY['help', 'find', 'land'], 10, 'en'),
('listings', 'I want to rent', 'Great! We have many properties available for rent. Browse our Apartments page for rental listings. You can filter by location, price, and size. What type of property are you looking to rent?', ARRAY['rent', 'rental', 'lease'], 10, 'en'),
('listings', 'I want to buy', 'Great! We have properties available for purchase. Browse our listings - apartments, houses, cars, and land plots. You can filter by category, location, and price. What are you looking to buy?', ARRAY['buy', 'purchase', 'sale'], 10, 'en'),
('listings', 'I want to sell', 'Great! You can sell your property on HOME AFRICA. Create an account, click "Post", and list your property. Fill in details, upload photos, and publish. Buyers will contact you directly. What are you selling?', ARRAY['sell', 'post', 'list'], 10, 'en'),
('listings', 'Cheap apartments', 'We have apartments at various price points. Use our Apartments page and sort by price or set a maximum price filter to find affordable options. What''s your budget?', ARRAY['cheap', 'affordable', 'budget', 'apartments'], 9, 'en'),
('listings', 'Affordable houses', 'We have houses at various price points. Check our Apartments page and use price filters to find affordable options. You can also sort by price. What''s your budget range?', ARRAY['affordable', 'cheap', 'budget', 'houses'], 9, 'en'),
('listings', 'Budget cars', 'We have cars at various price points. Visit our Cars page and use price filters or sort by price to find budget-friendly options. What''s your budget?', ARRAY['budget', 'cheap', 'affordable', 'cars'], 9, 'en'),
('listings', 'Cheap land', 'We have land plots at various prices. Check our Land Plots page and use price filters to find affordable options. Prices vary by location and size. What area are you interested in?', ARRAY['cheap', 'affordable', 'budget', 'land'], 9, 'en'),
('listings', 'Luxury apartments', 'We have apartments across all price ranges, including luxury options. Premium apartments typically feature prime locations, larger sizes, and premium amenities. Check our Apartments page and filter by price. What are you looking for?', ARRAY['luxury', 'premium', 'high end', 'apartments'], 8, 'en'),
('listings', 'Premium houses', 'We have houses across all price ranges, including premium properties. Luxury houses feature prime locations, larger sizes, and premium amenities. Browse our Apartments page. What are your preferences?', ARRAY['premium', 'luxury', 'high end', 'houses'], 8, 'en'),
('listings', 'Luxury cars', 'We have cars across all price ranges, including luxury vehicles. Premium cars feature newer models, better brands, and lower mileage. Visit our Cars page and filter by price. What are you looking for?', ARRAY['luxury', 'premium', 'high end', 'cars'], 8, 'en'),
('listings', 'Near me', 'I can help you find properties near your location! Tell me what area you''re in or interested in, and I can help you search. You can also use location filters on our website. What area are you in?', ARRAY['near me', 'close', 'nearby', 'location'], 9, 'en'),
('listings', 'Close to city center', 'We have properties close to city centers, especially in Kigali. City center locations offer convenience but may be more expensive. Check our listings and filter by location. What type of property are you looking for?', ARRAY['city center', 'downtown', 'central', 'close'], 8, 'en'),
('listings', 'Near airport', 'We may have properties near airports. Airport proximity offers convenience for frequent travelers. Check our listings and filter by location. What type of property are you looking for?', ARRAY['airport', 'near airport', 'close'], 7, 'en'),
('listings', 'Near university', 'We have properties near universities and educational institutions. These locations are popular with students and staff. Check our listings and filter by location. What area are you interested in?', ARRAY['university', 'college', 'school', 'near'], 8, 'en'),

