-- SECTION 16: INVESTMENT & FINANCIAL QUESTIONS (300+ entries)
-- =====================================================

('investment', 'Is real estate a good investment', 'Real estate can be a good investment, offering potential appreciation, rental income, and portfolio diversification. Property values in Rwanda, especially Kigali, have shown growth. Consider location, market conditions, and your financial goals. What type of property interests you?', ARRAY['investment', 'good investment', 'real estate investment'], 9, 'en'),
('investment', 'Should I invest in property', 'Property investment can be profitable, especially in growing markets like Rwanda. Consider factors like location, property type, your budget, and investment goals. Real estate offers both rental income and potential appreciation. What are your investment goals?', ARRAY['invest', 'investment', 'property investment'], 9, 'en'),
('investment', 'What is ROI', 'ROI (Return on Investment) measures investment profitability. For real estate, ROI considers rental income, appreciation, and costs. Good properties in prime locations typically offer better ROI. Location and property type affect ROI significantly.', ARRAY['roi', 'return', 'profit', 'investment return'], 8, 'en'),
('investment', 'How do I calculate property ROI', 'Property ROI considers rental income, appreciation, and expenses. Basic formula: (Annual Rental Income - Annual Expenses) / Property Cost × 100. Higher ROI indicates better investment. Location and property condition affect ROI.', ARRAY['calculate roi', 'roi calculation', 'return calculation'], 7, 'en'),
('investment', 'What property has best ROI', 'Properties in prime locations with good rental demand typically offer best ROI. Apartments in central Kigali often have strong rental yields. Consider location, property type, and market conditions. What are your investment goals?', ARRAY['best roi', 'best investment', 'profitable'], 8, 'en'),
('investment', 'Is buying better than renting', 'Buying vs renting depends on your situation. Buying builds equity and offers stability but requires down payment and maintenance. Renting offers flexibility but no equity. Consider your financial situation, plans, and market conditions.', ARRAY['buy vs rent', 'buying', 'renting', 'which better'], 8, 'en'),
('investment', 'What is rental yield', 'Rental yield is annual rental income as percentage of property value. Higher yield means better rental returns. Good rental yields in Kigali can range from 5-10% depending on location and property type. Check listings for rental potential.', ARRAY['rental yield', 'yield', 'rental return'], 7, 'en'),
('investment', 'Should I buy land or house', 'Land vs house depends on goals. Land offers development potential and may appreciate, but requires construction. Houses provide immediate use and rental income. Consider your budget, timeline, and goals. What are you planning?', ARRAY['land vs house', 'buy land', 'buy house'], 8, 'en'),
('investment', 'Is property a safe investment', 'Property is generally considered a safer long-term investment than stocks, offering tangible assets and potential appreciation. However, values can fluctuate. Well-located properties in growing areas like Kigali tend to be safer investments.', ARRAY['safe investment', 'risk', 'secure'], 8, 'en'),
('investment', 'How much should I invest', 'Investment amount depends on your financial situation, goals, and risk tolerance. Never invest more than you can afford. Consider down payments, closing costs, and reserves. Consult financial advisors for personalized advice. What''s your budget?', ARRAY['how much invest', 'investment amount', 'budget'], 7, 'en'),

