-- SECTION 17: LEGAL & REGULATORY QUESTIONS (200+ entries)
-- =====================================================

('legal', 'What documents do I need to buy property', 'To buy property, you typically need: valid ID, proof of funds, title deed verification, and legal assistance. Land purchases require title transfer documents. Always work with a lawyer for property transactions. I can help you find properties!', ARRAY['documents', 'legal', 'requirements', 'buy property'], 9, 'en'),
('legal', 'Do I need a lawyer to buy property', 'While not always legally required, hiring a lawyer is highly recommended for property purchases. Lawyers handle title verification, contract review, and ensure legal compliance. Legal assistance protects your investment. Always verify property legality.', ARRAY['lawyer', 'legal assistance', 'attorney'], 9, 'en'),
('legal', 'What is title verification', 'Title verification confirms property ownership and checks for liens, encumbrances, or disputes. It ensures the seller legally owns the property and can transfer it. Always verify title before purchasing. This protects your investment.', ARRAY['title verification', 'verify title', 'ownership check'], 9, 'en'),
('legal', 'What is a property deed', 'A property deed is a legal document transferring property ownership from seller to buyer. Deeds must be registered with authorities. Proper deeds ensure legal ownership. Always verify deeds before purchasing property.', ARRAY['deed', 'property deed', 'ownership document'], 9, 'en'),
('legal', 'What are property rights', 'Property rights include ownership, use, and transfer rights. Property owners can use, rent, or sell their property within legal limits. Zoning and regulations may restrict certain uses. Understand rights before purchasing.', ARRAY['property rights', 'rights', 'ownership rights'], 8, 'en'),
('legal', 'What is property registration', 'Property registration records ownership with government authorities. Registration provides legal proof of ownership and protects against disputes. All property transactions should be properly registered. Verify registration before buying.', ARRAY['registration', 'property registration', 'register'], 9, 'en'),
('legal', 'What is a lease agreement', 'A lease agreement is a contract between landlord and tenant specifying rent, duration, and terms. Leases protect both parties. Always read lease agreements carefully before signing. Understand all terms and conditions.', ARRAY['lease agreement', 'lease', 'rental contract'], 9, 'en'),
('legal', 'What are tenant rights', 'Tenant rights include habitable living conditions, privacy, and fair treatment. Landlords must maintain properties and respect tenant privacy. Understand your rights as a tenant. Leases should protect tenant rights.', ARRAY['tenant rights', 'rights', 'tenant protection'], 8, 'en'),
('legal', 'What are landlord rights', 'Landlord rights include receiving rent, property access for maintenance, and eviction for non-payment or lease violations. Landlords can set rent and lease terms within legal limits. Understand rights before renting out property.', ARRAY['landlord rights', 'rights', 'property owner rights'], 8, 'en'),
('legal', 'Can I evict a tenant', 'Eviction procedures depend on local laws and lease terms. Typically requires notice and valid reasons like non-payment or lease violations. Follow legal procedures. Consult lawyers for eviction processes. Always follow local regulations.', ARRAY['evict', 'eviction', 'remove tenant'], 7, 'en'),
('legal', 'What is property tax', 'Property tax is an annual tax on property ownership, paid to local government. Tax amounts depend on property value and location. Property taxes fund local services. Budget for property taxes when owning property.', ARRAY['property tax', 'tax', 'annual tax'], 8, 'en'),
('legal', 'Do I pay tax on rental income', 'Rental income may be subject to income tax depending on local laws. Tax rates and requirements vary. Consult tax advisors for rental income tax obligations. Keep records of rental income and expenses.', ARRAY['rental tax', 'income tax', 'tax on rent'], 7, 'en'),
('legal', 'What is capital gains tax', 'Capital gains tax applies to profit from selling property. Tax rates depend on holding period and local laws. Some jurisdictions offer exemptions. Consult tax advisors about capital gains when selling property.', ARRAY['capital gains', 'tax', 'sale tax'], 7, 'en'),

-- =====================================================
-- SECTION 18: PROPERTY MAINTENANCE & CARE (200+ entries)
-- =====================================================

('maintenance', 'How do I maintain my property', 'Property maintenance includes regular cleaning, repairs, and upkeep. For rentals, landlords typically handle major repairs while tenants handle daily maintenance. For owned properties, budget 1-2% of value annually for maintenance. What type of property do you have?', ARRAY['maintenance', 'upkeep', 'care', 'property care'], 8, 'en'),
('maintenance', 'What maintenance does property need', 'Property maintenance includes: plumbing, electrical, roofing, painting, cleaning, and landscaping. Regular maintenance prevents costly repairs. Budget for ongoing maintenance costs. Well-maintained properties retain value better.', ARRAY['maintenance needs', 'upkeep', 'repairs'], 8, 'en'),
('maintenance', 'How much does property maintenance cost', 'Maintenance costs typically range from 1-2% of property value annually. Costs vary by property type, age, and condition. Apartments may have lower maintenance than houses. Budget for unexpected repairs. What type of property?', ARRAY['maintenance cost', 'cost', 'expenses'], 7, 'en'),
('maintenance', 'Who pays for repairs', 'For rentals, landlords typically pay for major repairs and structural issues, while tenants handle minor maintenance. Lease agreements specify responsibilities. For owned properties, owners pay all maintenance. Check lease terms for details.', ARRAY['repairs', 'who pays', 'maintenance responsibility'], 8, 'en'),
('maintenance', 'What is property insurance', 'Property insurance protects against damage from fire, theft, natural disasters, and liability. Insurance is important for property owners. Rental properties may require landlord insurance. Consult insurance providers for coverage options.', ARRAY['insurance', 'property insurance', 'coverage'], 8, 'en'),
('maintenance', 'Do I need property insurance', 'Property insurance is highly recommended to protect your investment. Insurance covers damage and liability. Some mortgages require insurance. Rental properties benefit from landlord insurance. Consult insurance providers for your needs.', ARRAY['need insurance', 'insurance required', 'coverage'], 8, 'en'),
('maintenance', 'How do I find a contractor', 'To find contractors, ask for recommendations, check reviews, verify licenses, and get multiple quotes. Good contractors are licensed, insured, and have good references. For property repairs, choose reputable contractors. Need help finding services?', ARRAY['contractor', 'repair', 'handyman', 'services'], 7, 'en'),
('maintenance', 'What is a property inspection', 'A property inspection evaluates property condition before purchase, identifying issues like structural problems, electrical issues, or needed repairs. Inspections help buyers make informed decisions and negotiate repairs. Consider inspections before buying.', ARRAY['inspection', 'property check', 'evaluation'], 8, 'en'),
('maintenance', 'How often should I inspect property', 'For owned properties, inspect regularly for maintenance needs. For rentals, landlords should inspect periodically with proper notice. Annual inspections help catch issues early. Regular maintenance prevents costly problems. What type of property?', ARRAY['inspect', 'inspection frequency', 'check property'], 7, 'en'),
('maintenance', 'What is preventive maintenance', 'Preventive maintenance is regular upkeep to prevent problems before they occur. Examples include cleaning gutters, servicing HVAC, checking for leaks. Preventive maintenance saves money long-term and extends property life.', ARRAY['preventive maintenance', 'upkeep', 'maintenance'], 7, 'en'),

